        elif ra[0] == a and rb[0] == b:
            routes[ra_id] = list(reversed(ra)) + rb
        elif ra[-1] == a and rb[-1] == b:
            routes[ra_id] = ra + list(reversed(rb))
        else:
            return False
        route_load[ra_id] = route_load.get(ra_id, 0) + route_load.get(rb_id, 0)
        routes[rb_id] = []
        route_load[rb_id] = 0
        for c in routes[ra_id]:
            route_of[c] = ra_id
        return True

    for s, ci, cj in savings:
        ri = route_of.get(ci, None)
        rj = route_of.get(cj, None)
        if ri is None or rj is None or ri == rj:
            continue
        if not routes[ri] or not routes[rj]:
            continue
        if route_load[ri] + route_load[rj] > capacity:
            continue
        ai0, ai1 = route_endpoints(routes[ri])
        bj0, bj1 = route_endpoints(routes[rj])
        can = False
        if (ci == ai1 and cj == bj0) or (ci == ai0 and cj == bj1) or (ci == ai0 and cj == bj0) or (ci == ai1 and cj == bj1):
            can = True
        if can:
            merge_routes(ri, rj, ci, cj)

    routes = [r for r in routes if r]

    # Route improvement: orient each route by nearest depot at ends
    for idx in range(len(routes)):
        r = routes[idx]
        if len(r) >= 2:
            if dist(depot, r[-1]) + dist(r[0], depot) < dist(depot, r[0]) + dist(r[-1], depot):
                routes[idx] = list(reversed(r))

    # Helper cost
    def route_cost(r):
        if not r:
            return 0.0
        c = dist(depot, r[0]) + dist(r[-1], depot)
        for i in range(len(r) - 1):
            c += dist(r[i], r[i + 1])
        return c

    # 2-opt within routes
    improved = True
    while improved:
        improved = False
        for ridx in range(len(routes)):
            r = routes[ridx]
            n = len(r)
            if n < 4:
                continue
            best_gain = 0.0
            best_i = best_j = None
            base = route_cost(r)
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    nr = r[:i + 1] + list(reversed(r[i + 1:j + 1])) + r[j + 1:]
                    nc = route_cost(nr)
                    gain = base - nc
                    if gain > best_gain + 1e-12:
                        best_gain = gain
                        best_i, best_j = i, j
            if best_gain > 1e-12:
                r = r[:best_i + 1] + list(reversed(r[best_i + 1:best_j + 1])) + r[best_j + 1:]
                routes[ridx] = r
                improved = True

    # Inter-route relocate and swap
    def load_of(r):
        s = 0
        for c in r:
            s += get_demand(c)
        return s

    changed = True
    while changed:
        changed = False
        # relocate single customer
        for i in range(len(routes)):
            for pos in range(len(routes[i])):
                c = routes[i][pos]
                dc = get_demand(c)
                best_delta = 0.0
                best_move = None
                for j in range(len(routes)):
                    if i == j:
                        continue
                    if load_of(routes[j]) + dc > capacity:
                        continue
                    r1 = routes[i]
                    r2 = routes[j]
                    for ins in range(len(r2) + 1):
                        nr1 = r1[:pos] + r1[pos + 1:]
                        nr2 = r2[:ins] + [c] + r2[ins:]
                        old = route_cost(r1) + route_cost(r2)
                        new = route_cost(nr1) + route_cost(nr2)
                        delta = old - new
                        if delta > best_delta + 1e-12:
                            best_delta = delta
                            best_move = (i, j, pos, ins)
                if best_move is not None:
                    i2, j2, pos, ins = best_move
                    c = routes[i2][pos]
                    routes[i2] = routes[i2][:pos] + routes[i2][pos + 1:]
                    routes[j2] = routes[j2][:ins] + [c] + routes[j2][ins:]
                    if not routes[i2]:
                        routes.pop(i2)
                    changed = True
                    break
            if changed:
                break

    # Final cleanup: remove empty routes, ensure deterministic order of routes
    routes = [r for r in routes if r]

    # If some customers missing due to unusual input, repair with singleton routes
    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1
    missing = [c for c in customers if seen.get(c, 0) == 0]
    for c in missing:
        routes.append([c])

    # If duplicates exist, keep first occurrence and repair the rest
    used = set()
    repaired = []
    for r in routes:
        nr = []
        for c in r:
            if c not in used:
                used.add(c)
                nr.append(c)
        if nr:
            repaired.append(nr)
    routes = repaired

    # Final capacity safeguard: split any overloaded route greedily
    final_routes = []
    for r in routes:
        cur = []
        cur_load = 0
        for c in r:
            dc = get_demand(c)
            if cur and cur_load + dc > capacity:
                final_routes.append(cur)
                cur = [c]
                cur_load = dc
            else:
                cur.append(c)
                cur_load += dc
        if cur:
            final_routes.append(cur)

    # If splitting introduced any missing customers, add singleton routes
    seen = {}
    for r in final_routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1
    for c in customers:
        if seen.get(c, 0) == 0:
            final_routes.append([c])

    # Sort routes deterministically by first customer then length
    final_routes.sort(key=lambda r: (r[0], len(r), sum(r) if all(isinstance(x, int) for x in r) else 0))
    return final_routes
